import math, json

def compute():
    vals = set()
    for a in range(1, 100):  # enough because a+b<=20 => a<=19
        for b in range(a+1, 100):
            if a + b not in (12, 15, 20):
                continue
            if math.gcd(a, b) != 1:
                continue
            vals.add(a * b)
    total = sum(vals)
    print(total)
    print(json.dumps(sorted(vals)))

if __name__ == "__main__":
    compute()

import json, math

def r2(n):
    # return number of integer solutions (x,y) to x^2+y^2=n, counting order and signs
    # factor n
    temp = n
    prod = 1
    for p in range(2, int(math.isqrt(temp)) + 1):
        if temp % p == 0:
            exp = 0
            while temp % p == 0:
                temp //= p
                exp += 1
            if p % 4 == 3:
                if exp % 2 == 1:
                    return 0
                # even exponent does not affect the product
            elif p % 4 == 1:
                prod *= (exp + 1)
            # p == 2 does not affect the product
    # remaining prime factor
    if temp > 1:
        if temp % 4 == 3:
            return 0
        elif temp % 4 == 1:
            prod *= 2  # exponent is 1, so (1+1)
    return 4 * prod

limit = 500
vals = []
for n in range(1, limit):
    if r2(n) == 12:
        vals.append(n)
ans = sum(vals)
print(ans)
print(json.dumps(sorted(vals)))

import json, math

def digit_set(n):
    return set(str(n))

N = 1_000_000
ans = 0
vals = []
for n in range(1, N+1):
    # condition 1: divisor of N
    if N % n != 0:
        continue
    # condition 2: perfect square
    r = int(math.isqrt(n))
    if r * r != n:
        continue
    # condition 3: exactly two distinct decimal digits
    if len(digit_set(n)) == 2:
        ans += n
        vals.append(n)

print(ans)
print(json.dumps(sorted(vals)))

import math, json

def lcm(a, b):
    return a * b // math.gcd(a, b)

solutions = []
for n in range(1, 1000):
    for k in range(1, 1000):
        if math.floor(n / math.gcd(n, k)) == 3 and lcm(n, k) == 210:
            solutions.append(n)
            break
solutions = sorted(set(solutions))
print(sum(solutions))
print(json.dumps(solutions))
